-------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Configuration of the CTLD plugin for missions generated by DCS Retribution, built on MOOSE's CTLD and AUTOLASE classes.
-- see https://github.com/dcs-retribution/dcs-retribution
--
-- One CTLD instance runs per coalition that has logistics flights. Retribution generates everything it needs:
--   * dcsRetribution.Logistics.flights          transport flights with their pickup, drop-off and target zones
--   * dcsRetribution.Logistics.transports       troop and crate capacity per aircraft type
--   * dcsRetribution.Logistics.troop_templates  late-activated troop groups offered as troop cargo
--   * dcsRetribution.Logistics.crate_templates  late-activated vehicle groups built from airlifted crates
--   * dcsRetribution.Logistics.crates           crates to spawn at mission start for client airlifts
--   * dcsRetribution.Carriers                   carriers and LHAs, which act as pickup zones
--   * dcsRetribution.JTACs                      front-line JTACs, lasing through AUTOLASE
--
-- MOOSE's CTLD only serves players, so AI transports are loaded and unloaded here: AI troop helicopters pick up troops
-- when they land in a pickup zone or on a carrier and drop them when they land in a drop-off zone. AI fixed-wing
-- transports start with troops on board and parachute them over their target zone, except the Anubis Hercules mod,
-- which drops paratroopers from its own loadout (see the Hercules cargo plugin).
-------------------------------------------------------------------------------------------------------------------------------------------------------------

-- Assumed mass of one soldier with kit, in kg.
local TROOP_MASS = 100
-- Mass of one airlift crate, in kg.
local CRATE_MASS = 500
-- Seconds between two checks for landed AI transports.
local AI_CHECK_INTERVAL = 2
-- Seconds between two zone smokes; a DCS smoke lasts about five minutes.
local ZONE_SMOKE_INTERVAL = 290
-- Size of the loading zone on a carrier deck, in metres.
local SHIP_LENGTH = 300
local SHIP_WIDTH = 60
-- Lasing range of the JTACs, in metres.
local JTAC_LASE_DISTANCE = 10000
-- The laser code FC3 aircraft (Su-25T, A-10A) can use.
local FC3_LASER_CODE = 1113
-- The Anubis Hercules mod. Retribution gives it paratroopers as bombs and a carpet-bombing task, so it drops its troops
-- without CTLD.
local ANUBIS_HERCULES = "Hercules"
-- Descent rate of a paratrooper under canopy, in m/s; paratroopers reach the ground this long after jumping.
local PARACHUTE_DESCENT_RATE = 5
-- Distance between two paratroopers on the ground, along the aircraft's track, in metres.
local PARATROOPER_SPACING = 15

local SIDE_NAMES = { [1] = "red", [2] = "blue" }

local function log(message, ...)
    env.info("DCSRetribution|CTLD plugin - " .. string.format(message, ...))
end

local function toboolean(value)
    return value == true or value == "true"
end

local function setup()
    local options = dcsRetribution.plugins.ctld
    local logistics = dcsRetribution.Logistics or {}
    local debug = toboolean(options.debug)
    local smoke_zones = toboolean(options.smoke)

    RetributionCTLD = { instances = {} }
    local instances = RetributionCTLD.instances

    -- Per-coalition setup ---------------------------------------------------------------------------------------------------------------------------------

    local function instance_for(side)
        side = tonumber(side)
        if not SIDE_NAMES[side] then
            return nil
        end
        if instances[side] then
            return instances[side]
        end

        local instance = {
            side = side,
            pilot_groups = {},
            -- Transport unit name -> { paradrop_zone }, for the AI loop. paradrop_zone is the target zone a fixed-wing
            -- transport parachutes its troops over, nil for transports that land to unload.
            pilot_units = {},
            -- Troop cargo by ascending size: { name, troops }.
            troops = {},
        }
        local pilot_groups = instance.pilot_groups
        local ctld = CTLD:New(SIDE_NAMES[side], { "Retribution" }, SIDE_NAMES[side] == "blue" and "Blue CTLD" or "Red CTLD")
        -- Only Retribution's transport flights get the CTLD menus.
        ctld:SetOwnSetPilotGroups(
            SET_GROUP:New()
                :FilterCoalitions(SIDE_NAMES[side])
                :FilterFunction(function(group)
                    return pilot_groups[group:GetName()] == true
                end)
                :FilterStart()
        )
        ctld.debug = debug
        ctld.enableslingload = toboolean(options.slingload)
        -- As with the original CTLD script, crates can be unpacked anywhere.
        ctld.dropcratesanywhere = true
        instance.ctld = ctld
        instances[side] = instance
        return instance
    end

    local transports = {}
    for _, transport in pairs(logistics.transports or {}) do
        transports[transport.aircraft_type] = transport
    end

    local function set_capabilities(instance, aircraft_type)
        local transport = transports[aircraft_type]
        if not transport then
            return
        end
        local ctld = instance.ctld
        local defaults = CTLD.UnitTypeCapabilities[aircraft_type] or {}
        local can_crates = toboolean(transport.crates)
        local can_troops = toboolean(transport.troops)
        local trooplimit = tonumber(transport.cabin_size) or 0
        local cratelimit = 0
        if can_crates then
            cratelimit = math.max(defaults.cratelimit or 0, 1)
        end
        -- MOOSE also checks cargo mass; make sure a full cabin of troops fits.
        local weightlimit = math.max(defaults.cargoweightlimit or 0, trooplimit * TROOP_MASS, can_crates and CRATE_MASS or 0)
        ctld:SetUnitCapabilities(aircraft_type, can_crates, can_troops, cratelimit, trooplimit, defaults.length, weightlimit)
        if not toboolean(transport.helicopter) then
            ctld.enableFixedWing = true
            ctld:AddAllowedFixedWingType(aircraft_type)
        end
    end

    -- Zones -----------------------------------------------------------------------------------------------------------------------------------------------

    local function add_zone(instance, zone_name, zone_type, color)
        if zone_name and zone_name ~= "" then
            instance.ctld:AddCTLDZone(zone_name, zone_type, color, true, false)
        end
    end

    local preload_units = {}
    for _, flight in pairs(logistics.flights or {}) do
        local instance = instance_for(flight.side)
        if instance then
            if flight.group_name then
                instance.pilot_groups[flight.group_name] = true
            end
            local transport = transports[flight.aircraft_type]
            local paradrop = transport ~= nil and not toboolean(transport.helicopter) and flight.aircraft_type ~= ANUBIS_HERCULES
            local paradrop_zone = nil
            if paradrop and flight.target_zone and flight.target_zone ~= "" then
                paradrop_zone = flight.target_zone
            end
            for _, pilot in pairs(flight.pilot_names or {}) do
                instance.pilot_units[pilot] = { paradrop_zone = paradrop_zone }
                if toboolean(flight.preload) then
                    preload_units[pilot] = instance
                end
            end
            set_capabilities(instance, flight.aircraft_type)
            add_zone(instance, flight.pickup_zone, CTLD.CargoZoneType.LOAD, SMOKECOLOR.Blue)
            add_zone(instance, flight.drop_off_zone, CTLD.CargoZoneType.DROP, SMOKECOLOR.Green)
            -- Troops dropped near a target zone move into it.
            add_zone(instance, flight.target_zone, CTLD.CargoZoneType.MOVE, SMOKECOLOR.Red)
        end
    end

    for _, carrier in pairs(dcsRetribution.Carriers or {}) do
        local unit = Unit.getByName(carrier.unit_name)
        local instance = unit and instances[unit:getCoalition()]
        if instance then
            instance.ctld:AddCTLDZone(carrier.unit_name, CTLD.CargoZoneType.SHIP, SMOKECOLOR.Blue, true, false, SHIP_LENGTH, SHIP_WIDTH)
        end
    end

    -- Cargo -----------------------------------------------------------------------------------------------------------------------------------------------

    for _, template in pairs(logistics.troop_templates or {}) do
        local instance = instances[tonumber(template.side)]
        if instance then
            local troops = tonumber(template.troops)
            instance.ctld:AddTroopsCargo(template.name, { template.template }, CTLD_CARGO.Enum.TROOPS, troops, TROOP_MASS)
            table.insert(instance.troops, { name = template.name, troops = troops })
        end
    end
    for _, instance in pairs(instances) do
        table.sort(instance.troops, function(a, b)
            return a.troops < b.troops
        end)
    end

    for _, template in pairs(logistics.crate_templates or {}) do
        local instance = instances[tonumber(template.side)]
        if instance then
            instance.ctld:AddCratesCargo(template.unit, { template.template }, CTLD_CARGO.Enum.VEHICLE, 1, CRATE_MASS)
        end
    end

    for side, instance in pairs(instances) do
        instance.ctld:Start()
        log("started for %s", SIDE_NAMES[side])
    end

    -- Troop loading ---------------------------------------------------------------------------------------------------------------------------------------

    --- The largest troop cargo that fits into the unit, or nil.
    local function largest_troop_cargo(instance, unit)
        local capabilities = instance.ctld:_GetUnitCapabilities(unit)
        if not capabilities.troops then
            return nil
        end
        local best = nil
        for _, troop in ipairs(instance.troops) do
            if troop.troops <= capabilities.trooplimit and troop.troops * TROOP_MASS <= capabilities.cargoweightlimit then
                best = troop
            end
        end
        return best and instance.ctld:_FindTroopsCargoObject(best.name) or nil
    end

    local function has_troops(instance, unit_name)
        local loaded = instance.ctld.Loaded_Cargo[unit_name]
        return loaded ~= nil and (loaded.Troopsloaded or 0) > 0
    end

    local function preload(instance, unit_name)
        local unit = UNIT:FindByName(unit_name)
        if not unit or not unit:IsAlive() then
            return false
        end
        if not has_troops(instance, unit_name) then
            local cargo = largest_troop_cargo(instance, unit)
            if cargo then
                log("preloading %s into %s", cargo:GetName(), unit_name)
                instance.ctld:PreloadTroops(unit, cargo:GetName())
            end
        end
        return true
    end

    -- Flights already in the air at mission start are loaded right away, the others once they spawn. The delay after the
    -- birth lets a joining player's slot settle first, as CTLD empties the cargo of a unit a player enters.
    TIMER:New(function()
        for unit_name, instance in pairs(preload_units) do
            if preload(instance, unit_name) then
                preload_units[unit_name] = nil
            end
        end
    end):Start(5)

    local birth_handler = {}
    function birth_handler:onEvent(event)
        if event.id ~= world.event.S_EVENT_BIRTH or not event.initiator or not event.initiator.getName then
            return
        end
        local unit_name = event.initiator:getName()
        local instance = preload_units[unit_name]
        if instance then
            TIMER:New(function()
                if preload(instance, unit_name) then
                    preload_units[unit_name] = nil
                end
            end):Start(5)
        end
    end
    world.addEventHandler(birth_handler)

    local function is_landed(instance, unit)
        -- Some helicopters (e.g. the CH-47F) report InAir while on the ground, so a unit within hover height of the ground
        -- counts as landed too. The terrain height under a carrier is the sea, so a unit on deck relies on InAir.
        return not unit:InAir() or not instance.ctld:IsUnitInAir(unit)
    end

    --- Spawns the paratroopers of one troop template where they land, strung out along the aircraft's track.
    local function land_paratroopers(instance, template, landing, heading, group, unit)
        local ctld = instance.ctld
        local template_group = _DATABASE:GetGroupTemplate(template)
        if not template_group then
            env.error("DCSRetribution|CTLD plugin - no troop template " .. tostring(template))
            return
        end
        local count = #template_group.units
        local positions = {}
        for index = 1, count do
            local offset = (index - (count + 1) / 2) * PARATROOPER_SPACING
            local position = landing:Translate(offset, heading):GetVec2()
            positions[index] = { x = position.x, y = position.y, heading = heading }
        end
        ctld.TroopCounter = ctld.TroopCounter + 1
        local troops = SPAWN:NewWithAlias(template, string.format("%s-%d", template, math.random(1, 100000)))
            :InitDelayOff()
            :InitCoalition(ctld.coalition)
            :InitSetUnitAbsolutePositions(positions)
            :InitValidateAndRepositionGroundUnits(ctld.validateAndRepositionUnits)
            :SpawnFromVec2(landing:GetVec2())
        ctld.DroppedTroops[ctld.TroopCounter] = troops
        -- Lets CTLD move the troops into the target zone, as with troops unloaded from a helicopter.
        ctld:__TroopsDeployed(1, group, unit, troops, CTLD_CARGO.Enum.TROOPS)
    end

    --- Drops the troops of an AI fixed-wing transport by parachute. MOOSE's own air drop puts the troops on the ground
    --- at once and only within narrow speed and height limits, which AI flights don't keep to.
    local function paradrop(instance, unit)
        local ctld = instance.ctld
        local unit_name = unit:GetName()
        local loaded = ctld.Loaded_Cargo[unit_name] or {}
        local remaining = { Troopsloaded = 0, Cratesloaded = 0, Cargo = {} }
        local templates = {}
        for _, cargo in pairs(loaded.Cargo or {}) do
            if not cargo:WasDropped() then
                if cargo:GetType() == CTLD_CARGO.Enum.TROOPS then
                    cargo:SetWasDropped(true)
                    for _, template in pairs(cargo:GetTemplates() or {}) do
                        table.insert(templates, template)
                    end
                else
                    table.insert(remaining.Cargo, cargo)
                    remaining.Cratesloaded = remaining.Cratesloaded + 1
                end
            end
        end
        ctld.Loaded_Cargo[unit_name] = remaining
        ctld:_UpdateUnitCargoMass(unit)

        local landing = unit:GetCoordinate()
        local height = math.max(landing.y - landing:GetLandHeight(), 0)
        local heading = unit:GetHeading() or 0
        local group = unit:GetGroup()
        log("AI %s parachutes %d troop group(s) from %d m", unit_name, #templates, height)
        TIMER:New(function()
            for _, template in ipairs(templates) do
                local ok, err = pcall(land_paratroopers, instance, template, landing, heading, group, unit)
                if not ok then
                    env.error("DCSRetribution|CTLD plugin - paradrop failed: " .. tostring(err))
                end
            end
        end):Start(math.max(height / PARACHUTE_DESCENT_RATE, 1))
    end

    local function service_ai_transports(instance)
        local ctld = instance.ctld
        for unit_name, transport in pairs(instance.pilot_units) do
            local unit = UNIT:FindByName(unit_name)
            if not unit or not unit:IsAlive() or unit:IsPlayer() then
                -- Not an AI transport in the mission (yet).
            elseif transport.paradrop_zone then
                if has_troops(instance, unit_name) and not is_landed(instance, unit) then
                    local zone = ZONE:FindByName(transport.paradrop_zone)
                    if zone and unit:IsInZone(zone) then
                        paradrop(instance, unit)
                    end
                end
            elseif is_landed(instance, unit) then
                if not has_troops(instance, unit_name) then
                    if ctld:IsUnitInZone(unit, CTLD.CargoZoneType.LOAD) or ctld:IsUnitInZone(unit, CTLD.CargoZoneType.SHIP) then
                        local cargo = largest_troop_cargo(instance, unit)
                        if cargo then
                            log("AI %s picks up %s", unit_name, cargo:GetName())
                            ctld:_LoadTroops(unit:GetGroup(), unit, cargo, true)
                        end
                    end
                elseif ctld:IsUnitInZone(unit, CTLD.CargoZoneType.DROP) then
                    log("AI %s drops its troops", unit_name)
                    ctld:_UnloadTroops(unit:GetGroup(), unit)
                end
            end
        end
    end

    TIMER:New(function()
        for _, instance in pairs(instances) do
            local ok, err = pcall(service_ai_transports, instance)
            if not ok then
                env.error("DCSRetribution|CTLD plugin - AI transport check failed: " .. tostring(err))
            end
        end
    end):Start(AI_CHECK_INTERVAL, AI_CHECK_INTERVAL)

    -- Airlift crates --------------------------------------------------------------------------------------------------------------------------------------

    if toboolean(options.airliftcrates) then
        TIMER:New(function()
            log("spawning airlift crates")
            for _, crate in pairs(logistics.crates or {}) do
                local instance = instances[tonumber(crate.side)]
                local zone = ZONE:FindByName(crate.zone)
                local template = instance and instance.ctld:_FindCratesCargoObject(crate.unit)
                if template and zone then
                    local ctld = instance.ctld
                    -- Every crate needs a cargo object of its own: CTLD tracks the crate through it.
                    ctld.CargoCounter = ctld.CargoCounter + 1
                    local cargo = CTLD_CARGO:New(ctld.CargoCounter, template.Name, template.Templates, CTLD_CARGO.Enum.VEHICLE, false, false, 1, nil, nil, CRATE_MASS)
                    cargo:SetStaticTypeAndShape("Cargos", ctld.basetype)
                    ctld:InjectStatics(zone, cargo, true)
                else
                    env.error(string.format("DCSRetribution|CTLD plugin - cannot spawn crate %s in zone %s", tostring(crate.unit), tostring(crate.zone)))
                end
            end
        end):Start(3)
    end

    -- Zone smoke ------------------------------------------------------------------------------------------------------------------------------------------

    if smoke_zones then
        TIMER:New(function()
            for _, instance in pairs(instances) do
                for _, zones in ipairs({ instance.ctld.pickupZones, instance.ctld.dropOffZones }) do
                    for _, ctld_zone in pairs(zones) do
                        local zone = ZONE:FindByName(ctld_zone.name)
                        if zone and ctld_zone.active then
                            zone:GetCoordinate():Smoke(ctld_zone.color)
                        end
                    end
                end
            end
        end):Start(1, ZONE_SMOKE_INTERVAL)
    end
end

-- JTAC autolase -------------------------------------------------------------------------------------------------------------------------------------------

local function setup_autolase()
    local options = dcsRetribution.plugins.ctld
    if not toboolean(options.autolase) then
        log("JTAC autolase disabled")
        return
    end
    local smoke = toboolean(options.jtacsmoke)
    local fc3 = toboolean(options.fc3LaserCode)

    local jtacs_by_side = {}
    for _, jtac in pairs(dcsRetribution.JTACs or {}) do
        local group = Group.getByName(jtac.dcsGroupName)
        if group then
            local side = group:getCoalition()
            jtacs_by_side[side] = jtacs_by_side[side] or {}
            table.insert(jtacs_by_side[side], jtac)
        else
            env.warning("DCSRetribution|CTLD plugin - JTAC group " .. tostring(jtac.dcsGroupName) .. " not found")
        end
    end

    RetributionCTLD = RetributionCTLD or { instances = {} }
    RetributionCTLD.autolase = {}
    for side, jtacs in pairs(jtacs_by_side) do
        if SIDE_NAMES[side] then
            local recce = SET_GROUP:New()
            for _, jtac in ipairs(jtacs) do
                recce:AddGroupsByName(jtac.dcsGroupName)
            end
            local autolase = AUTOLASE:New(recce, SIDE_NAMES[side], "Retribution JTAC")
            autolase:SetLasingParameters(JTAC_LASE_DISTANCE, 3600)
            autolase:SetLaserCoolDown(false)
            autolase:SetMaxLasingTargets(#jtacs)
            if smoke then
                autolase:SetSmokeTargets(true, SMOKECOLOR.Red)
            end
            for _, jtac in ipairs(jtacs) do
                -- FC3 aircraft (Su-25T, A-10A) can only use laser code 1113.
                local code = fc3 and FC3_LASER_CODE or tonumber(jtac.laserCode)
                log("JTAC %s lases with code %s", jtac.dcsGroupName, tostring(code))
                autolase:SetRecceLaserCode(jtac.dcsUnit, code)
            end
            RetributionCTLD.autolase[side] = autolase
        end
    end
end

if dcsRetribution and dcsRetribution.plugins and dcsRetribution.plugins.ctld then
    log("setting up")
    setup()
    setup_autolase()
end
